import React, { useState } from 'react';
import axios from 'axios';

function VulnScanner() {
  const [url, setUrl] = useState('');
  const [report, setReport] = useState(null);

  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const scan = async () => {
    setError(null);
    setReport(null);

    if (!url) {
      setError('Enter a target URL to scan.');
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post('/api/vuln/scan', { url });
      setReport(res.data);
    } catch (err) {
      setError(err.response?.data?.error || 'Scan failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h2>Website Vulnerability Scanner</h2>
        <button className="btn btn-sm btn-outline-light" onClick={() => window.location.reload()}>
          Reset
        </button>
      </div>

      <div className="card bg-dark text-white mb-4">
        <div className="card-body">
          <div className="input-group">
            <input
              type="text"
              className="form-control"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://example.com"
            />
            <button className="btn btn-primary" onClick={scan} disabled={loading}>
              {loading ? 'Scanning…' : 'Scan'}
            </button>
          </div>
          {error && <div className="alert alert-danger mt-3">{error}</div>}
        </div>
      </div>

      {report && (
        <div className="card bg-dark text-white">
          <div className="card-body">
            <h4 className="card-title">Scan Results</h4>
            <div className="mb-3">
              <strong>Target:</strong> {report.target}
            </div>
            <div className="row mb-3">
              {Object.entries(report.counts || {}).map(([level, count]) => (
                <div key={level} className="col-md-3 mb-2">
                  <div className="card text-dark">
                    <div className="card-body p-2">
                      <h6 className="card-title mb-1">{level}</h6>
                      <p className="card-text display-6 mb-0">{count}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            {report.details && report.details.length > 0 ? (
              <div>
                <h5>Vulnerabilities</h5>
                <div className="list-group">
                  {report.details.map((vuln, idx) => (
                    <div key={idx} className="list-group-item list-group-item-dark">
                      <div className="d-flex justify-content-between">
                        <strong>{vuln.name}</strong>
                        <span
                          className={`badge bg-${
                            vuln.level === 'Critical'
                              ? 'danger'
                              : vuln.level === 'High'
                              ? 'warning'
                              : vuln.level === 'Medium'
                              ? 'info'
                              : 'secondary'
                          }`}
                        >
                          {vuln.level}
                        </span>
                      </div>
                      <p className="mb-1">{vuln.description}</p>
                      <small className="text-muted">Fix: {vuln.fix}</small>
                      {vuln.evidence && (
                        <div className="mt-1">
                          <small className="text-muted">Evidence: {vuln.evidence}</small>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <p>No vulnerabilities found.</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default VulnScanner;
